<script setup>
import { onMounted, ref, computed, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { uploadListingMedia } from '../../api/tools/imageCropper.js';
import { materialBindings, categoryKey } from '../../../../src/shared/workflow-materials.js';
import {moldMappingRows,exportMoldCsv,parseMoldCsv,isKeyMold} from '../../../../src/shared/key-mold-mapping.js';
import PageFooterPagination from '../PageFooterPagination.vue';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
import WorkflowBrandModels from './WorkflowBrandModels.vue';
import OzonCategorySelect from './OzonCategorySelect.vue';
const props=defineProps({standalone:Boolean,selectable:Boolean,selectedIds:{type:Array,default:()=>[]},seed:{type:Object,default:()=>({})},category:{type:Object,default:()=>({})}}),emit=defineEmits(['saved','select']);
const records=ref([]),keyword=ref(''),busy=ref(false),editor=ref(false),current=ref(null),form=ref({}),preview=ref(null),categoryFilter=ref(categoryKey(props.category)||''),brandFilter=ref(''),modelFilter=ref(''),formCategoryKey=ref(''),general=ref(false);
const page=ref(1),pageSize=ref(12),total=ref(0),roleFilter=ref(props.seed.role||''),catalog=ref([]);let loadSequence=0;
const availability=ref('active');
const view=ref('cards'),reviewFilter=ref(''),csvInput=ref(null),importRows=ref(null);
const mappingRows=computed(()=>moldMappingRows(records.value).map(row=>({...row,record:records.value.find(r=>r.id===row.id)})));

const brandOptions=computed(()=>catalog.value.map(b=>b.name));
const modelOptions=computed(()=>(catalog.value.find(b=>b.name===brandFilter.value)?.models||[]).map(m=>m.name));
const visible=computed(()=>records.value);
const imageNode=computed(()=>({id:'material_images',type:'images',label:'资料图片',count:form.value.images?.length||1,slots:Array.from({length:form.value.images?.length||1},(_,i)=>`资料图 ${i+1}`)}));
const bindingsLabel=p=>materialBindings(p).map(b=>`${b.brand}：${b.allModels?'全部型号':b.models.join('、')}`).join('；')||(p.unresolvedBindings?.length?'旧型号未绑定系统目录，请编辑重新选择':'通用资料 · 未限制品牌型号');
async function load(){const sequence=++loadSequence;busy.value=true;try{const query=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value),keyword:keyword.value,category:categoryFilter.value,brand:brandFilter.value,model:modelFilter.value,role:roleFilter.value,reviewStatus:reviewFilter.value,availability:availability.value});const result=await apiClient.get('/api/product-workflows/material-library?'+query,{noCache:true});if(sequence!==loadSequence)return;records.value=result.items;total.value=result.total;page.value=result.page;}catch(e){if(sequence===loadSequence)ElMessage.error(e.message);}finally{if(sequence===loadSequence)busy.value=false;}}
function search(){page.value=1;load();}
watch([categoryFilter,brandFilter,modelFilter,roleFilter,reviewFilter,availability],search);
function edit(record){current.value=record||null;const p=record?.payload;form.value=p?JSON.parse(JSON.stringify({...p,name:record.kind==='key_model'?p.label:p.name||record.name,bindings:materialBindings(p)})):{name:'',coreName:'',searchTerms:'',reviewStatus:'pending',moldCode:'',shape:'',yearRange:'',sourceUrl:'',buttonCount:0,category:roleFilter.value==='compatibility'?'钥匙模具':'',material:'',role:props.seed.images?.length||roleFilter.value==='compatibility'?'compatibility':'style',notes:'',images:props.seed.images?.length?[...props.seed.images]:[''],bindings:props.seed.bindings||[],listingCategory:categoryKey(props.category)?{key:categoryKey(props.category),name:props.category.categoryName||props.category.name}:null};form.value.reviewStatus||='verified';formCategoryKey.value=categoryKey(form.value.listingCategory);general.value=record?!formCategoryKey.value:false;editor.value=true;}
function selectCategory(chosen){form.value.listingCategory={key:chosen.ozon_category_id,name:chosen.path_zh||chosen.category_name_zh||chosen.category_name||chosen.path||chosen.name};}
async function upload(file,index){busy.value=true;try{const result=await uploadListingMedia(file,{source_module:'product_workflow_material',role:form.value.role}),url=result.publishUrl||result.url||result.previewUrl;if(!url)throw new Error('图片上传未返回地址');form.value.images[index]=url;ElMessage.success('图片已上传，请点击保存到企业资料完成入库');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function save(){busy.value=true;try{if(!general.value&&!formCategoryKey.value)throw new Error('请从类目树选择类目，或选择跨类目通用资料');const payload={...form.value,listingCategory:general.value?null:form.value.listingCategory};if(current.value?.kind==='key_model'){const first=payload.bindings[0];Object.assign(payload,{brand:first?.brand||'',model:first?.models?.[0]||'',label:payload.name});}const saved=await apiClient.post(`/api/product-workflows/${current.value?.kind==='key_model'?'key-models':'materials'}`,{id:current.value?.id,revision:current.value?.revision,payload});editor.value=false;await load();emit('saved',saved);ElMessage.success('已保存企业生产资料');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function archive(record){const enabling=Boolean(record.payload.archived);try{await ElMessageBox.confirm(enabling?'启用后，这份资料可以再次被新任务引用。':'停用后不能用于新任务，可在“已停用”中重新启用；历史任务保留资料快照。',enabling?'启用生产资料':'停用生产资料',{confirmButtonText:enabling?'启用':'停用',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=true;try{await apiClient.post(`/api/product-workflows/${record.kind==='key_model'?'key-models':'materials'}`,{id:record.id,revision:record.revision,payload:{...record.payload,archived:!enabling}});preview.value=null;await load();emit('saved');ElMessage.success(enabling?'资料已启用':'资料已停用');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function remove(record){try{await ElMessageBox.confirm('删除后资料将从资料库移除，不再用于新任务；历史任务、已生成图片和已有文件会保留。','删除生产资料',{confirmButtonText:'确认删除',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=true;try{await apiClient.post('/api/product-workflows/archive',{kind:record.kind,id:record.id,revision:record.revision});if(preview.value?.id===record.id)preview.value=null;await load();emit('saved');ElMessage.success('资料已删除');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}

async function confirmMold(record){if(record.payload.unresolvedBindings?.length)return edit(record);try{await ElMessageBox.confirm(`请确认图片与以下适配范围一致：${bindingsLabel(record.payload)}。确认后可用于自动匹配。`,'确认适配关系',{confirmButtonText:'已核对，启用自动匹配',cancelButtonText:'返回核对'});}catch{return;}busy.value=true;try{const saved=await apiClient.post(`/api/product-workflows/${record.kind==='key_model'?'key-models':'materials'}`,{id:record.id,revision:record.revision,payload:{...record.payload,reviewStatus:'verified'}});if(preview.value?.id===record.id)preview.value=saved;await load();emit('saved');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
function downloadCsv(text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='钥匙模具适配映射表.csv';link.click();URL.revokeObjectURL(url);}
async function exportMapping(){busy.value=true;try{const query=new URLSearchParams({keyword:keyword.value,category:categoryFilter.value,brand:brandFilter.value,model:modelFilter.value,reviewStatus:reviewFilter.value,availability:availability.value});downloadCsv(exportMoldCsv(await apiClient.get('/api/product-workflows/mold-mappings?'+query,{noCache:true})));}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function readCsv(event){try{const file=event.target.files?.[0];if(!file)return;if(file.size>2*1024*1024)throw new Error('映射表最多2 MB，请分批导入');importRows.value=parseMoldCsv(await file.text());}catch(e){ElMessage.error(e.message);}finally{event.target.value='';}}
async function applyImport(){busy.value=true;try{const result=await apiClient.post('/api/product-workflows/mold-mappings',{records:importRows.value});importRows.value=null;await load();emit('saved');ElMessage.success(`已保存${result.count}份模具，原图片和历史任务保持原样`);}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
function setView(value){view.value=value;roleFilter.value=value==='mapping'?'compatibility':(props.seed.role||'');}
onMounted(async()=>{apiClient.get('/api/ai-variant-lab/vehicle-catalog',{noCache:true}).then(result=>catalog.value=result.brands||[]).catch(()=>{});await load();if(props.seed.create)edit();});
</script>
<template>
 <div class="material-library" v-loading="busy"><div class="material-toolbar"><el-input v-model="keyword" clearable placeholder="搜索类目、核心品名、资料名称、品牌或型号" @keyup.enter="search" @clear="search"/><el-button type="primary" @click="search">搜索</el-button><el-button @click="load">刷新</el-button><el-button type="primary" @click="edit()">新增生产资料</el-button></div><div class="material-filters"><OzonCategorySelect v-model="categoryFilter" :show-sync="false" placeholder="按类目筛选（同时展示通用资料）"/><el-select v-model="brandFilter" clearable filterable placeholder="品牌筛选" @change="modelFilter='' "><el-option v-for="brand in brandOptions" :key="brand" :label="brand" :value="brand"/></el-select><el-select v-model="modelFilter" clearable filterable placeholder="型号筛选" :disabled="!brandFilter"><el-option v-for="model in modelOptions" :key="model" :label="model" :value="model"/></el-select></div><div class="material-mode"><el-select v-model="availability" aria-label="资料状态"><el-option label="已启用" value="active"/><el-option label="已停用" value="disabled"/><el-option label="全部状态" value="all"/></el-select><el-select v-model="reviewFilter" clearable placeholder="核对状态"><el-option label="待核对" value="pending"/><el-option label="已核对" value="verified"/></el-select><el-radio-group :model-value="view" @change="setView"><el-radio-button value="cards">图片卡片</el-radio-button><el-radio-button value="mapping">适配映射表</el-radio-button></el-radio-group><el-button @click="exportMapping">导出映射表</el-button><el-button @click="csvInput.click()">导入映射表</el-button><input ref="csvInput" type="file" accept=".csv" hidden @change="readCsv"/></div><p class="hint">按类目管理图片与适配关系。模具按外形、按键和年款核对；待核对资料不参与自动匹配，核对后启用。停用可再次启用；删除从资料库移除，历史快照和文件保留。</p>
 <el-empty v-if="!visible.length" description="没有匹配资料，可调整筛选或新增"/>
 <div v-if="view==='cards'" class="material-cards"><article v-for="record in visible" :key="record.id"><WorkflowValuePreview :value="record.payload.images" format="images"/><div><strong>{{ record.name }}</strong><el-tag v-if="record.payload.archived" type="info" size="small">已停用</el-tag><el-tag v-if="isKeyMold(record)" size="small" :type="record.payload.reviewStatus==='pending'?'warning':'success'">{{ record.payload.reviewStatus==='pending'?'待核对':'已核对' }}</el-tag><p>{{ record.payload.listingCategory?.name||'通用 / 尚未分类' }} · {{ [record.payload.coreName,record.payload.category].filter(Boolean).join(' · ')||record.payload.label||'生产资料' }}</p><small>{{ bindingsLabel(record.payload) }}</small><el-tag v-if="record.payload.unresolvedBindings?.length" type="warning" size="small">{{ record.payload.unresolvedBindings.length }} 项旧型号待绑定目录</el-tag><small v-if="record.payload.yearRange">{{ record.payload.yearRange }}</small><div class="material-actions"><el-button v-if="selectable&&!record.payload.archived" type="primary" size="small" :plain="selectedIds.includes(record.id)" @click="emit('select',record)">{{ selectedIds.includes(record.id)?'已引用':'引用这份资料' }}</el-button><el-button v-if="isKeyMold(record)&&record.payload.reviewStatus==='pending'" size="small" type="success" plain @click="preview=record">核对适配</el-button><el-button size="small" @click="preview=record">查看</el-button><el-button size="small" @click="edit(record)">编辑</el-button><el-button size="small" :type="record.payload.archived?'success':'warning'" plain @click="archive(record)">{{ record.payload.archived?'启用':'停用' }}</el-button><el-button size="small" type="danger" plain @click="remove(record)">删除</el-button></div></div></article></div>
 <el-table v-else :data="mappingRows" class="mapping-table" height="100%" border><el-table-column label="模具图片" width="100"><template #default="{row}"><WorkflowValuePreview :value="row.record.payload.images" format="images"/></template></el-table-column><el-table-column prop="moldCode" label="编号" width="130"/><el-table-column prop="name" label="模具名称" min-width="170"/><el-table-column prop="brand" label="已绑定品牌" width="150"/><el-table-column prop="models" label="已绑定型号" min-width="180"/><el-table-column prop="yearRange" label="年款 / 限制" min-width="200"/><el-table-column prop="buttonCount" label="按键" width="65"/><el-table-column label="核对" width="100"><template #default="{row}"><el-tag :type="row.reviewStatus==='pending'?'warning':'success'">{{ row.reviewStatus==='pending'?'待核对':'已核对' }}</el-tag></template></el-table-column><el-table-column label="操作" width="300" fixed="right"><template #default="{row}"><div class="material-actions"><el-button size="small" @click="preview=row.record">查看</el-button><el-button size="small" @click="edit(row.record)">编辑</el-button><el-button size="small" :type="row.record.payload.archived?'success':'warning'" plain @click="archive(row.record)">{{ row.record.payload.archived?'启用':'停用' }}</el-button><el-button size="small" type="danger" plain @click="remove(row.record)">删除</el-button></div></template></el-table-column></el-table>
 <PageFooterPagination :page="page" :page-size="pageSize" :total="total" :page-sizes="[12,24,48]" :disabled="busy" @update:page="page=$event;load()" @update:page-size="pageSize=$event;search()"/>
 <el-dialog :model-value="Boolean(preview)" @update:model-value="!$event&&(preview=null)" :title="preview?.name||'资料预览'" width="700px" append-to-body><template v-if="preview"><p>{{ preview.payload.listingCategory?.name||'通用资料' }}</p><p>{{ bindingsLabel(preview.payload) }}</p><WorkflowValuePreview :value="preview.payload.images" format="images"/><p>{{ preview.payload.moldCode }} · {{ preview.payload.buttonCount||'按键待核对' }} · {{ preview.payload.shape }}</p><p>{{ preview.payload.yearRange }}</p><el-link v-if="preview.payload.sourceUrl" :href="preview.payload.sourceUrl" target="_blank" type="primary">查看资料来源</el-link><WorkflowValuePreview :value="preview.payload.notes" label="完整资料说明"/><el-button v-if="isKeyMold(preview)&&preview.payload.reviewStatus==='pending'" type="success" @click="confirmMold(preview)">已核对，启用自动匹配</el-button><el-button v-if="selectable&&!preview.payload.archived" type="primary" @click="emit('select',preview)">引用这份资料</el-button></template></el-dialog>
 <el-dialog v-model="editor" append-to-body :title="current?'编辑生产资料':'新增生产资料'" width="760px" top="4vh" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" class="workflow-material-dialog"><el-form label-position="top" :disabled="busy"><el-form-item label="适用类目"><el-checkbox v-model="general">跨类目通用资料（例如通用礼盒、店铺宣传图）</el-checkbox><OzonCategorySelect v-if="!general" v-model="formCategoryKey" :show-sync="false" :display-label="form.listingCategory?.name||''" @select="selectCategory"/></el-form-item><el-form-item label="资料名称" required><el-input v-model="form.name" placeholder="例如：钥匙模具 A、黑色礼盒成品详情图" maxlength="180"/></el-form-item><el-form-item label="核心品名"><el-input v-model="form.coreName" placeholder="例如：钥匙壳、门槛条、礼盒"/></el-form-item><el-form-item label="补充搜索词"><el-input v-model="form.searchTerms" placeholder="例如：钥匙套 汽车防盗报警器保护套"/></el-form-item><el-alert v-if="form.unresolvedBindings?.length" type="warning" :closable="false" :title="'旧绑定未匹配系统目录：'+form.unresolvedBindings.map(b=>b.brand+' '+b.model).join('、')+'。请核对后重新选择，不能直接作为适配绑定。'"/><el-form-item label="绑定品牌 / 绑定型号（从系统目录选择，可留空）"><WorkflowBrandModels v-model="form.bindings" :disabled="busy" allow-all @update:model-value="form.unresolvedBindings=[]"/></el-form-item><div class="material-fields"><el-form-item label="材质（选填）"><el-input v-model="form.material" placeholder="只填写已确认的材质"/></el-form-item><el-form-item label="资料类型（自定义）"><el-input v-model="form.category" placeholder="例如：钥匙模具、包装、店铺宣传图"/></el-form-item></div><el-form-item label="参考用途"><el-select v-model="form.role"><el-option label="版式 / 风格参考" value="style"/><el-option label="适配对象参考（例如钥匙模具）" value="compatibility"/><el-option label="真实产品资料" value="product"/></el-select></el-form-item><template v-if="form.role==='compatibility'||current?.kind==='key_model'"><div class="material-fields"><el-form-item label="模具编号"><el-input v-model="form.moldCode" placeholder="例如 BENZ-M01"/></el-form-item><el-form-item label="按键数量（0表示待核对）"><el-input-number v-model="form.buttonCount" :min="0" :max="12"/></el-form-item></div><el-form-item label="外形特征"><el-input v-model="form.shape" placeholder="例如：黑银长条，三键，底部挂孔"/></el-form-item><el-form-item label="年款及适配限制"><el-input v-model="form.yearRange" placeholder="同型号可能有多种模具，填写已核实年款与限制"/></el-form-item><el-form-item label="来源链接"><el-input v-model="form.sourceUrl" placeholder="HTTPS 来源或产品资料链接"/></el-form-item><el-form-item label="适配核对状态"><el-radio-group v-model="form.reviewStatus"><el-radio value="pending">待核对</el-radio><el-radio value="verified">已核对，可自动匹配</el-radio></el-radio-group></el-form-item></template><el-form-item label="资料说明"><el-input v-model="form.notes" type="textarea" :rows="3" placeholder="填写用途、已核实事实和使用限制"/></el-form-item><el-form-item label="资料图片（最多 8 张，支持拖入）"><WorkflowMaterialInput v-model="form.images" compact :node="imageNode" :disabled="busy" @upload="upload"/><el-button :disabled="busy||form.images.length>=8" @click="form.images.push('')">增加图片</el-button></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="editor=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存到企业资料</el-button></template></el-dialog><el-dialog :model-value="Boolean(importRows)" @update:model-value="!$event&&(importRows=null)" title="确认导入适配映射表" width="720px" append-to-body><p>共{{ importRows?.length }}份模具。已有资料按ID和版本更新，新编号另存；任何一份失败都不写入。</p><el-table :data="importRows||[]" max-height="360"><el-table-column prop="patch.name" label="模具名称"/><el-table-column prop="patch.moldCode" label="编号"/><el-table-column label="核对状态"><template #default="{row}">{{ row.patch.reviewStatus==='pending'?'待核对':'已核对' }}</template></el-table-column></el-table><template #footer><el-button @click="importRows=null">取消</el-button><el-button type="primary" :loading="busy" @click="applyImport">确认保存映射表</el-button></template></el-dialog></div>
</template>
<style scoped>
.material-library>.erp-footer-pagination{margin:0;flex-shrink:0}.material-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px}.material-actions>.el-button+.el-button{margin-left:0}

.material-library{display:flex;flex-direction:column;height:72vh;min-height:400px;overflow:hidden}.material-toolbar,.material-filters,.material-kind,.hint{flex-shrink:0}.material-kind{margin-top:12px}.material-mode{display:flex;gap:10px;align-items:center;margin-top:12px;flex-wrap:wrap;flex-shrink:0}.material-mode>.el-select{width:130px}.material-mode .material-kind{margin-top:0}.mapping-table{min-height:0;flex:1}.mapping-table :deep(.preview-images .el-image){width:64px;height:84px}.material-toolbar{display:flex;gap:10px}.material-toolbar .el-input{max-width:520px;margin-right:auto}.material-filters{display:grid;grid-template-columns:minmax(220px,2fr) 1fr 1fr;gap:12px;margin-top:14px}.hint{color:var(--el-text-color-secondary);font-size:13px;line-height:1.8}.material-cards{display:grid;gap:12px;min-height:0;flex:1;overflow:auto;align-content:start}.material-cards article{display:flex;gap:16px;border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:16px}.material-cards article>.value-preview{width:150px;flex-shrink:0}.material-cards p,.material-cards small{color:var(--el-text-color-secondary);line-height:1.6}.material-cards small{display:block;margin-bottom:12px}.material-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.el-select{width:100%}.material-library :deep(.el-form-item__content){display:block}@media(max-width:650px){.material-filters{grid-template-columns:1fr}.material-cards article{flex-wrap:wrap}}
</style>
<style>.workflow-material-dialog .el-dialog__body{max-height:70vh;overflow:auto}</style>
